  "[data-vc-root] textarea:focus,[data-vc-root] input:focus{outline:2px solid var(--dsws-ring-color,var(--dsw-focus-ring-color,var(--dsw-alias-state-business-primary,#58a6ff)));outline-offset:-2px}",
