  "[data-vc-shell] .vcs-hist-graph-note,[data-vc-shell] .vcs-hist-graph-capped,[data-vc-shell] .vcs-hist-graph-narrow{margin:2px 0 0;color:var(--vcs-dim);font-size:12px;overflow-wrap:anywhere}",
  "[data-vc-shell] .vcs-hist-graph-rows{margin:4px 0 0;padding:0;list-style:none;display:grid;gap:1px}",
