  "[data-vc-shell] .vc-wt-current-path{display:flex;flex-wrap:wrap;gap:2px;margin-top:2px;font-family:ui-monospace,monospace;font-size:11px;color:var(--vcs-dim);overflow-wrap:anywhere}",
  "[data-vc-shell] .vc-wt-head{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:8px 8px 0}",
