  "[data-vc-shell] .vc-wt-filters{display:flex;flex-wrap:wrap;gap:4px;margin-left:auto}",
  "[data-vc-shell] .vc-wt-filter{font:inherit;font-size:12px;padding:2px 8px;border:1px solid var(--vcs-line);border-radius:999px;background:transparent;color:var(--vcs-dim);cursor:pointer}",
  "[data-vc-shell] .vc-wt-filter.is-on{border-color:var(--vcs-accent);color:var(--vcs-accent)}",
  "[data-vc-shell] .vc-wt-rows{list-style:none;margin:0;padding:0 8px;display:flex;flex-direction:column;gap:4px}",
  "[data-vc-shell] .vc-wt-row{border:1px solid var(--vcs-line);border-radius:4px;background:var(--vcs-panel)}",
