  "[data-vc-shell] .vc-wt-name-row{display:flex;flex-wrap:wrap;gap:6px;align-items:center}",
  "[data-vc-shell] .vc-wt-name{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:60%}",
  "[data-vc-shell] .vc-wt-branch{color:var(--vcs-dim);font-size:12px}",
  "[data-vc-shell] .vc-wt-oid{color:var(--vcs-dim);font-family:ui-monospace,monospace;font-size:11px}",
  "[data-vc-shell] .vc-wt-row-path{display:flex;flex-wrap:wrap;gap:2px;font-family:ui-monospace,monospace;font-size:11px;color:var(--vcs-dim);overflow-wrap:anywhere}",
  "[data-vc-shell] .vc-wt-states{display:flex;flex-wrap:wrap;gap:4px}",
