  "[data-vc-shell] .toggle-btn.is-on {",
  "  background: var(--accent-soft); border-color: color-mix(in srgb, var(--accent) 40%, transparent); color: var(--accent); font-weight: 650; }",
  "[data-vc-shell] .history-scope-row { display: flex; align-items: center; gap: 8px; padding: 0 12px 6px; border-bottom: 1px solid var(--line); }",
  "[data-vc-shell] .history-scope {",
  "  flex: 1; min-width: 0; font-family: var(--mono); font-size: 10px; color: var(--faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }",
