  if (model.remotes.length > 0) {
    listKids.push(h("ul", { key: "list", className: "vcs-remote-list", role: "list", "aria-label": t("vc.remote.listLabel") }, model.remotes.map(function(remote) {
      return vcRemoteRowNode(h, t, model, remote);
    })));
  }
